package org.com.sharekhan.research.ema921;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.com.sharekhan.research.ema921.Ema921Engine.*;
class Ema921EngineTest {
    static Config config(int tf){return new Config(tf,LocalTime.of(9,30),LocalTime.of(14,30),null,null,0.005,0,null,List.of());}
    static List<Bar> bars(){var result=new ArrayList<Bar>();for(int d=0;d<4;d++)for(int m=0;m<375;m++){double p=23000+150*Math.sin((d*375+m)/20d);result.add(new Bar(LocalDate.of(2026,1,5).atTime(9,15).plusDays(d).plusMinutes(m),p,p+1,p-1,p));}return result;}
    @Test void allTimeframesUseClosedBarsAndSameDaySquareOff(){for(int tf:List.of(5,15,30)){var r=new Ema921Engine().run(bars(),List.of(),config(tf));assertFalse(r.trades().isEmpty());for(var t:r.trades()){var s=t.signal();assertEquals(s.entryAt().toLocalDate(),s.exitAt().toLocalDate());assertTrue(s.exitAt().toLocalTime().compareTo(SQUARE_OFF)<=0);assertEquals(0,Duration.between(s.entryAt().toLocalDate().atTime(OPEN),s.entryAt()).toMinutes()%tf);assertEquals(s.signalAt(),s.entryAt());assertTrue(s.entryAt().isBefore(s.exitAt()));assertNull(t.net());}assertEquals("INCOMPLETE",r.metrics().get(0).status());}}
    @Test void oppositeCrossReversesAtSameMinuteAndAfterCutoffOnlyExits(){var r=new Ema921Engine().run(bars(),List.of(),config(5));var plans=r.trades().stream().filter(t->t.mode()==Mode.ATM_BUY).map(Trade::signal).toList();boolean reversed=false,late=false;for(int i=0;i<plans.size()-1;i++){var t=plans.get(i);if(t.reason().equals("OPPOSITE_CROSS")&&t.exitAt().toLocalTime().compareTo(LocalTime.of(14,30))<=0){assertEquals(t.exitAt(),plans.get(i+1).entryAt());assertNotEquals(t.direction(),plans.get(i+1).direction());reversed=true;}if(t.exitAt().toLocalTime().isAfter(LocalTime.of(14,30)))late=true;}assertTrue(reversed);assertTrue(late);}
    @Test void missingSessionMinuteRejectsWholeDayAndResetsHistory(){var data=new ArrayList<>(bars());data.remove(400);var r=new Ema921Engine().run(data,List.of(),config(30));assertEquals("REJECTED",r.days().get(1).status());assertTrue(r.trades().stream().noneMatch(t->t.signal().entryAt().toLocalDate().equals(LocalDate.of(2026,1,6))));assertTrue(r.candles().stream().filter(c->c.at().toLocalDate().equals(LocalDate.of(2026,1,7))).findFirst().orElseThrow().ema21()==null);}
    @Test void constantAndTiedEmasDoNotCreateInitialTrade(){var data=bars().stream().map(b->new Bar(b.at(),23000,23000,23000,23000)).toList();var r=new Ema921Engine().run(data,List.of(),config(5));assertTrue(r.trades().isEmpty());assertTrue(r.days().stream().allMatch(d->d.status().equals("NO_TRADES")));}
    @Test void smaSeedAndRecurrence(){var ema=new Ema(3);assertNull(ema.add(1));assertNull(ema.add(2));assertEquals(2,ema.add(3));assertEquals(3,ema.add(4));}
    @Test void futurePricesCannotChangeEarlierSignals(){var original=bars();var mutated=original.stream().map(b->b.at().isAfter(LocalDateTime.of(2026,1,6,12,0))?new Bar(b.at(),30000,30001,29999,30000):b).toList();var a=new Ema921Engine().run(original,List.of(),config(5));var b=new Ema921Engine().run(mutated,List.of(),config(5));var end=LocalDateTime.of(2026,1,6,12,0);assertEquals(a.trades().stream().filter(t->t.signal().exitAt().isBefore(end)).toList(),b.trades().stream().filter(t->t.signal().exitAt().isBefore(end)).toList());}
    static List<OptionBar> quotes(List<Bar> bars){var result=new ArrayList<OptionBar>();for(int strike=22500;strike<=23500;strike+=50)for(String side:List.of("CE","PE")){var c=new Contract("C"+strike+side,LocalDate.of(2025,12,1),LocalDate.of(2026,1,13),strike,side,65);for(int i=0;i<bars.size();i++){double p=100+i*.01;result.add(new OptionBar(c,new Bar(bars.get(i).at(),p,p,p,p)));}}return result;}
    @Test void exactContractsModesLotsAndFullFeeStack(){var data=bars();var base=config(5);var f=new Fees(LocalDate.of(2026,1,1),LocalDate.of(2026,1,31),"Synthetic fee fixture",20,.001,.00035,.000001,.00003,.18,.000005);var c=new Config(5,base.start(),base.cutoff(),null,null,.005,0,100000d,List.of(f));var r=new Ema921Engine().run(data,quotes(data),c);for(var t:r.trades()){assertEquals("PRICED",t.status());boolean bull=t.signal().direction().equals("BULLISH"),buy=t.mode()!=Mode.ATM_SELL;assertEquals((bull==buy)?"CE":"PE",t.contract().right());assertEquals(65,t.contract().lotSize());double expected=(buy?1:-1)*(t.exitPremium()-t.entryPremium())*65;assertEquals(money(expected),t.gross());assertEquals(money(t.gross()-t.costs().total()),t.net());assertEquals(40,t.costs().brokerage());assertEquals(money((40+t.costs().exchange()+t.costs().sebi()+t.costs().ipft())*.18),t.costs().gst());assertTrue(t.costs().slippage()>=0);}assertTrue(r.metrics().stream().allMatch(m->m.status().equals("COMPLETE")));}
    @Test void missingExitCannotUseNewAtmContract(){var data=bars();var quotes=quotes(data);var plans=new Ema921Engine().run(data,List.of(),config(5));var first=plans.trades().get(0).signal();var missing=quotes.stream().filter(q->!q.bar().at().equals(first.exitAt())).toList();var r=new Ema921Engine().run(data,missing,config(5));assertTrue(r.trades().stream().filter(t->t.signal().id()==first.id()).allMatch(t->t.status().equals("UNPRICED")));assertTrue(r.metrics().stream().allMatch(m->m.net()==null));}
    @Test void noFeesWithholdsNetAndMissingDatesDoNotUseCurrentFees(){var data=bars();var r=new Ema921Engine().run(data,quotes(data),config(5));assertTrue(r.trades().stream().allMatch(t->t.status().equals("GROSS_ONLY")&&t.net()==null&&t.gross()!=null));assertTrue(r.metrics().stream().allMatch(m->m.net()==null&&m.gross()!=null));}
    @Test void fillsAdverseTickRoundedAndNonpositiveRejected(){var c=config(5);assertEquals(100.55,fill(100.01,true,c),1e-8);assertEquals(99.5,fill(100.01,false,c),1e-8);assertTrue(fill(.05,false,new Config(5,c.start(),c.cutoff(),null,null,0,.1,null,List.of()))<=0);}
    @Test void duplicateAndConflictingDataRejected(){var data=new ArrayList<>(bars());data.add(data.get(0));assertThrows(IllegalArgumentException.class,()->new Ema921Engine().run(data,List.of(),config(5)));assertThrows(IllegalArgumentException.class,()->new Bar(LocalDateTime.of(2026,1,1,9,15),100,90,99,100));assertThrows(IllegalArgumentException.class,()->new Config(10,LocalTime.of(9,30),LocalTime.of(14,30),null,null,0,0,null,List.of()));}
    @Test void dateFilterHasPriorWarmupAndOverlapIsRequired(){var c=config(5);var all=new Ema921Engine().run(bars(),List.of(),c);var date=LocalDate.of(2026,1,7);var r=new Ema921Engine().run(bars(),List.of(),new Config(5,c.start(),c.cutoff(),date,date,0,0,null,List.of()));assertEquals(all.trades().stream().filter(t->t.signal().entryAt().toLocalDate().equals(date)).map(t->t.signal().entryAt()).toList(),r.trades().stream().map(t->t.signal().entryAt()).toList());assertThrows(IllegalArgumentException.class,()->new Ema921Engine().run(bars(),List.of(),new Config(5,c.start(),c.cutoff(),date.plusYears(1),null,0,0,null,List.of())));}
}
